{"python":"import re, statistics

def col_letter(n):
    s=''
    while n:
        n, r = divmod(n-1, 26)
        s = chr(65+r)+s
    return s

def ref(file, sheet, r, c):
    return f"{file}/{sheet}/{col_letter(c+1)}{r+1}"

file5 = 'Source data figure 5.xlsx'
sheets5 = ['5l','5m','5n','5o']
all_rows = {}
for sh in sheets5:
    try:
        all_rows[sh] = get_rows(file5, sh)
    except Exception:
        all_rows[sh] = []

# Also inspect clinical workbook for RECIST labels if needed.
try:
    clin_rows = get_rows('mmc2.xlsx','Sheet1')
except Exception:
    clin_rows = []

pid_re = re.compile(r'^P\d+$', re.I)
label_map = {'CR':0,'PR':0,'SD':1,'PD':1}

# Index patient rows in Figure 5 source sheets.
patient_data = {}
labels = {}
for sh, rows in all_rows.items():
    for i,row in enumerate(rows):
        pid = None
        pid_col = None
        for c,v in enumerate(row):
            if isinstance(v,str) and pid_re.match(v.strip()):
                pid = v.strip().upper(); pid_col = c; break
        if not pid:
            continue
        patient_data.setdefault(pid, {})[sh] = (i,row)
        for c,v in enumerate(row):
            if isinstance(v,str) and v.strip().upper() in label_map and pid not in labels:
                labels[pid] = (v.strip().upper(), ref(file5,sh,i,c))

# Fallback: clinical labels in Table S1.
if len(labels) < 22:
    for i,row in enumerate(clin_rows):
        for c,v in enumerate(row):
            if isinstance(v,str) and pid_re.match(v.strip()):
                pid = v.strip().upper()
                for c2,v2 in enumerate(row):
                    if isinstance(v2,str) and v2.strip().upper() in label_map and pid not in labels:
                        labels[pid] = (v2.strip().upper(), ref('mmc2.xlsx','Sheet1',i,c2))

pids = sorted(patient_data.keys(), key=lambda x:int(x[1:]))

# Find numeric optimized-model readout columns and test their published ROC cutoffs.
candidates = []
for sh in ['5l','5m']:
    rows = all_rows.get(sh, [])
    if not rows: continue
    first_pid = min(i for i,row in enumerate(rows) if any(isinstance(v,str) and pid_re.match(v.strip()) for v in row))
    ncols = max(len(r) for r in rows)
    for c in range(ncols):
        header = ' '.join(str(rows[r][c]) if c < len(rows[r]) else '' for r in range(first_pid)).lower()
        vals = []
        refs = []
        for pid in pids:
            if sh not in patient_data.get(pid,{}): continue
            i,row = patient_data[pid][sh]
            if c >= len(row): continue
            v = row[c]
            if isinstance(v,(int,float)) and not isinstance(v,bool):
                vals.append(float(v)); refs.append(ref(file5,sh,i,c))
        if len(vals) != 22:
            continue
        med = statistics.median(vals)
        if not (0 <= med <= 100):
            continue
        scale = 100.0 if med > 1.5 else 1.0
        for th in [0.4897,0.5047]:
            pred = [1 if v/scale > th else 0 for v in vals]
            truth = [label_map[labels[p][0]] for p in pids]
            tp = sum(p==1 and t==1 for p,t in zip(pred,truth))
            tn = sum(p==0 and t==0 for p,t in zip(pred,truth))
            fp = sum(p==1 and t==0 for p,t in zip(pred,truth))
            fn = sum(p==0 and t==1 for p,t in zip(pred,truth))
            acc = (tp+tn)/22
            # Prefer explicitly optimized columns; require published confusion pattern.
            opt_bonus = 2 if (('optimized' in header or 'educated' in header) and ('original' not in header)) else 0
            if acc == 19/22 and tp==9 and tn==10:
                candidates.append((opt_bonus, sh, c, th, scale, refs, header, tp,tn,fp,fn))

status = 'computed'
records = []
threshold = None
readout = 'size_viability'
explanation = 'Optimized perfused tumoroid-on-a-chip response compared with RECIST 1.1 clinical outcome after FOLFOX + bevacizumab.'

if candidates:
    candidates.sort(reverse=True, key=lambda x:x[0])
    _, sh, c, th, scale, refs, header, tp,tn,fp,fn = candidates[0]
    threshold = th
    if 'vessel' in header or 'density' in header:
        readout = 'vessel_size'
    elif 'tumor' in header or 'diameter' in header:
        readout = 'size_viability'
    for pid, r in zip(pids, refs):
        score = {'ref': r} if scale == 1.0 else {'calc':'divide','args':[{'ref':r},100]}
        records.append({'id':pid,'score':score,'truth':{'ref':labels[pid][1],'map':{'CR':0,'PR':0,'SD':1,'PD':1}}})
else:
    status = 'blocked'
    explanation = 'Could not locate 22 row-level optimized-chip measurements whose ROC cutoff classifications give the reported 19/22 accuracy.'

CONTRACT = {
  'status': status,
  'fields': {
    'unit': {'value':'patient','evidence':['article:p76'],'explanation':'22 individual patient-derived chip models were compared with each patient’s clinical response.'},
    'platform': {'value':'perfused_chip','evidence':['article:p75','article:p76'],'explanation':'Vascularized colorectal tumoroid-on-a-chip with self-assembled perfused vessels.'},
    'readout': {'value':readout,'evidence':['article:p76'],'explanation':'Drug response was quantified by relative vessel density and relative tumoroid diameter; the bound score column is the source readout reproducing the headline.'},
    'direction': {'value':'lower_sensitive','evidence':['article:p76'],'explanation':'Lower relative vessel density or tumoroid diameter indicates drug sensitivity; higher values indicate resistance.'},
    'threshold_rule': {'value':'roc_optimized','evidence':['article:p76'],'explanation':'Optimal cutoffs were selected with the Youden index and bootstrap sampling.'},
    'threshold_timing': {'value':'outcome_optimized','evidence':['article:p76'],'explanation':'Cutoffs were determined using outcomes for the same 22 evaluated patients.'},
    'patient_mapping': {'value':'individual_available','evidence':['article:p76'],'explanation':'Each chip result is linked to an individual patient ID and clinical outcome.'},
    'regimen_match': {'value':'matched','evidence':['article:p76'],'explanation':'Both assay and clinical outcome concern FOLFOX plus bevacizumab.'},
    'n_units': {'value':22,'evidence':['article:p76'],'explanation':'The exact validation denominator is 22 patients.'},
    'split': {'value':'same_cohort','evidence':['article:p76'],'explanation':'No independent held-out cohort is reported; the cutoff was optimized in this validation cohort.'}
  },
  'headline': {
    'metric':'accuracy',
    'reported':0.8636363636363636,
    'reported_evidence':['article:p76'],
    'threshold':threshold,
    'op':'>',
    'score_direction':'higher',
    'records':records,
    'blocked_reason':None if status=='computed' else explanation
  },
  'notes':['CR and PR are mapped to clinical sensitivity (truth 0); SD and PD are mapped to clinical resistance (truth 1), as specified in the article.','Positive class for sensitivity is clinical resistance, matching the article definition.']
}
print('patients', len(pids), 'labels', len(labels), 'candidates', len(candidates))
print(CONTRACT['status'], CONTRACT['headline']['threshold'], len(CONTRACT['headline']['records']))"}
